/**
 * Field-map loader — the compiler's view of the intake contract.
 *
 * Sheet 08 of the customer intake template (generated by tools/intake/generate.py)
 * maps every intake field to the workflow-config keys it feeds. This module reads
 * the generated CSV; the generator is the single source of truth and is consumed
 * read-only (D3c task boundary).
 */
import type { FieldMapEntry } from './types.js'

export class FieldMapError extends Error {}

/** Columns of the generated field-map CSV (keep in sync with tools/intake/generate.py). */
const FIELDMAP_COLUMNS = [
  '序号 No.',
  'intake 键 Intake key',
  '所属表 Sheet',
  '来源行 Source row',
  '是否必填 Required',
  '喂入配置键 Config key(s)',
  '所属 Agent',
  '备注 Notes',
] as const

/**
 * Parse a CSV document (RFC 4180 subset: quoted fields, escaped quotes,
 * embedded newlines, CR/LF record ends). The intake generator emits QUOTE_ALL
 * CSV, but the parser is a full RFC 4180 reader so template evolution cannot
 * silently corrupt the field map.
 */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = []
  let row: string[] = []
  let field = ''
  let inQuotes = false
  let i = 0
  while (i < text.length) {
    const ch = text.charAt(i)
    if (inQuotes) {
      if (ch === '"') {
        if (text.charAt(i + 1) === '"') {
          field += '"'
          i += 2
          continue
        }
        inQuotes = false
        i += 1
        continue
      }
      field += ch
      i += 1
      continue
    }
    if (ch === '"' && field.length === 0) {
      inQuotes = true
      i += 1
      continue
    }
    if (ch === ',') {
      row.push(field)
      field = ''
      i += 1
      continue
    }
    if (ch === '\n') {
      row.push(field)
      field = ''
      rows.push(row)
      row = []
      i += 1
      continue
    }
    if (ch === '\r') {
      i += 1
      continue
    }
    field += ch
    i += 1
  }
  if (field.length > 0 || row.length > 0) {
    row.push(field)
    rows.push(row)
  }
  return rows
}

/** `competitors.list[0]` → `competitors.list` — indexed template rows become one list field. */
export function normalizeIntakeKey(intakeKey: string): string {
  return intakeKey.replace(/\[\d+\]$/, '')
}

export class FieldMap {
  private readonly byKey: ReadonlyMap<string, FieldMapEntry>
  private readonly byConfigKey: Map<string, FieldMapEntry[]>

  private constructor(
    readonly entries: readonly FieldMapEntry[],
    private readonly configKeysSet: ReadonlySet<string>,
  ) {
    this.byKey = new Map(entries.map((entry) => [entry.intakeKey, entry]))
    this.byConfigKey = new Map()
    for (const entry of entries) {
      for (const key of entry.configKeys) {
        const bucket = this.byConfigKey.get(key) ?? []
        bucket.push(entry)
        this.byConfigKey.set(key, bucket)
      }
    }
  }

  static fromCsv(text: string): FieldMap {
    const rows = parseCsv(text)
    const header = rows[0]
    if (header === undefined || header.length < FIELDMAP_COLUMNS.length) {
      throw new FieldMapError(
        `field map CSV header does not match the generator output (expected columns: ${FIELDMAP_COLUMNS.join(', ')})`,
      )
    }
    for (const [index, expected] of FIELDMAP_COLUMNS.entries()) {
      if (header[index] !== expected) {
        throw new FieldMapError(
          `field map CSV column ${index} is "${String(header[index])}", expected "${expected}" — was the template regenerated?`,
        )
      }
    }

    const entries: FieldMapEntry[] = []
    const seen = new Set<string>()
    for (const row of rows.slice(1)) {
      if (row.length < FIELDMAP_COLUMNS.length) continue
      const intakeKey = row[1]?.trim() ?? ''
      if (!intakeKey) continue
      if (seen.has(intakeKey)) {
        throw new FieldMapError(`duplicate intake key in field map: ${intakeKey}`)
      }
      seen.add(intakeKey)
      const configKeys = (row[5] ?? '')
        .split(/[;；]/)
        .map((key) => key.trim())
        .filter((key) => key.length > 0)
      if (configKeys.length === 0) {
        throw new FieldMapError(`intake key ${intakeKey} feeds no config keys — fix the template's field map`)
      }
      entries.push({
        no: row[0]?.trim() ?? '',
        intakeKey,
        sheet: row[2]?.trim() ?? '',
        sourceRow: row[3]?.trim() ?? '',
        required: (row[4] ?? '').trim().startsWith('必填'),
        configKeys,
        agent: row[6]?.trim() ?? '',
        note: row[7]?.trim() ?? '',
      })
    }
    if (entries.length === 0) {
      throw new FieldMapError('field map CSV has no data rows')
    }
    return new FieldMap(entries, new Set(entries.flatMap((entry) => [...entry.configKeys])))
  }

  /** Distinct config keys across the whole map (the traceability vocabulary). */
  get configKeys(): ReadonlySet<string> {
    return this.configKeysSet
  }

  entry(intakeKey: string): FieldMapEntry | undefined {
    return this.byKey.get(intakeKey)
  }

  /** Entry for an incoming intake path, matching indexed template rows to their list form. */
  entryForPath(path: string): FieldMapEntry | undefined {
    return this.byKey.get(path) ?? this.byKey.get(`${path}[0]`)
  }

  /** Does any intake field live at or below this path? (Used to reject unknown answers.) */
  coversPath(path: string): boolean {
    return this.entries.some((entry) => {
      const key = normalizeIntakeKey(entry.intakeKey)
      return key === path || key.startsWith(`${path}.`)
    })
  }

  /** Intake fields feeding a config key — reverse lookup for audit and tests. */
  entriesForConfigKey(configKey: string): readonly FieldMapEntry[] {
    return this.byConfigKey.get(configKey) ?? []
  }
}
